import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [, second] = input;
const p = second.split(" ").map(Number);

// その日より前の最安値で買ったと考える
let minPrice = p[0];
let best = 0;
for (let j = 1; j < p.length; j++) {
  best = Math.max(best, p[j] - minPrice);
  minPrice = Math.min(minPrice, p[j]);
}
console.log(best);
